def _placement(p):
    if p.Placement is not None:
        return p.Placement
    return _fx.r3_new_frame(_fx.r3_new_vec(0, 0, 0), _fx.r3_new_vec(1, 0, 0), _fx.r3_new_vec(0, 1, 0))

def _region_with_holes(s, holes, stage):
    found = None
    for candidate in s.profiles():
        if candidate.Valid and (len(candidate.Holes) == holes):
            if found is not None:
                raise RuntimeError("%s: more than one region has %d holes" % (stage, holes,))
            found = candidate
    if found is None:
        raise RuntimeError("%s: no valid region with %d holes among %d regions" % (stage, holes, len(s.profiles()),))
    return found

def _solve_and_verify(s, stage):
    s.solve()
    _fx.sketchcheck_verify_fully_constrained(s)
    return

def _disc_point(p, d, t, cx, cy, phi):
    n = float(p.PinCount)
    r, e = d.pinCircleRadius, p.Eccentricity
    num = math.sin((1 - n) * t)
    den = (r / (e * n)) - math.cos((1 - n) * t)
    psi = math.atan2(num, den)
    x0 = ((r * math.cos(t)) - (d.effectiveRadius * math.cos(t + psi))) - (e * math.cos(n * t))
    y0 = ((-r * math.sin(t)) + (d.effectiveRadius * math.sin(t + psi))) + (e * math.sin(n * t))
    return _Point(x=(cx + (x0 * math.cos(phi))) - (y0 * math.sin(phi)), y=(cy + (x0 * math.sin(phi))) + (y0 * math.cos(phi)))

def _lobe_parameters(p, d, turnLimit):
    lobes = float(d.lobes)
    span = (2 * math.pi) / lobes
    fine = [None] * (_lobe_fine_steps + 1)
    for i in range(len(fine)):
        fine[i] = _disc_point(p, d, (span * float(i)) / _lobe_fine_steps, 0, 0, 0)
    def direction(a, b):
        return math.atan2(b.y - a.y, b.x - a.x)
    kept = [0]
    turn = 0.0
    for i in range(1, _lobe_fine_steps):
        delta = direction(fine[i], fine[i + 1]) - direction(fine[i - 1], fine[i])
        while delta > math.pi:
            delta = delta - (2 * math.pi)
        while delta < -math.pi:
            delta = delta + (2 * math.pi)
        turn = turn + abs(delta)
        if turn >= turnLimit:
            kept = kept + [(span * float(i)) / _lobe_fine_steps]
            turn = 0
    return kept + [span]

def _profile_curvature(p, d, t):
    h = 1e-6
    a = _disc_point(p, d, t - h, 0, 0, 0)
    b = _disc_point(p, d, t, 0, 0, 0)
    c = _disc_point(p, d, t + h, 0, 0, 0)
    x1, y1 = (c.x - a.x) / (2 * h), (c.y - a.y) / (2 * h)
    x2, y2 = ((c.x - (2 * b.x)) + a.x) / (h * h), ((c.y - (2 * b.y)) + a.y) / (h * h)
    return (x1 * y2) - (y1 * x2)

def _inflections(p, d):
    span = (2 * math.pi) / float(d.lobes)
    steps = 4000
    def inside(t):
        return min(max(t, span * 1e-5), span * (1 - 1e-5))
    out = []
    prev = span * 1e-5
    for i in range(1, steps + 1):
        cur = inside((span * float(i)) / steps)
        if (_profile_curvature(p, d, prev) > 0) != (_profile_curvature(p, d, cur) > 0):
            lo, hi = prev, cur
            for _ in range(60):
                mid = (lo + hi) / 2
                if (_profile_curvature(p, d, mid) > 0) == (_profile_curvature(p, d, lo) > 0):
                    lo = mid
                else:
                    hi = mid
            out = out + [(lo + hi) / 2]
        prev = cur
    return out

def _lobe_segments(p, d, turnLimit):
    span = (2 * math.pi) / float(d.lobes)
    cuts = _inflections(p, d)
    segments = []
    current = []
    next = 0
    for t in _lobe_parameters(p, d, turnLimit):
        while (next < len(cuts)) and (cuts[next] <= t):
            current = current + [cuts[next]]
            segments = segments + [current]
            current = [cuts[next]]
            next += 1
        if (len(current) > 0) and ((t - current[len(current) - 1]) < (span * 1e-4)):
            continue
        current = current + [t]
    return segments + [current]

def _housing_contour(p, d):
    n = float(p.PinCount)
    half = math.pi / n
    reach = [0.0] * (_contour_points)
    hit = [False] * (_contour_points)
    trace = [None] * (_contour_curve_steps + 1)
    for i in range(_contour_cam_steps):
        theta = ((2 * math.pi) * float(i)) / _contour_cam_steps
        cx, cy = p.Eccentricity * math.cos(theta), p.Eccentricity * math.sin(theta)
        phi = -theta / float(d.lobes)
        for j in range(len(trace)):
            trace[j] = _disc_point(p, d, ((2 * math.pi) * float(j)) / _contour_curve_steps, cx, cy, phi)
        for j in range(_contour_curve_steps):
            a, b = trace[j], trace[j + 1]
            alpha, beta = math.atan2(a.y, a.x), math.atan2(b.y, b.x)
            if (beta - alpha) > math.pi:
                beta = beta - (2 * math.pi)
            elif (alpha - beta) > math.pi:
                beta = beta + (2 * math.pi)
            lo, hi = min(alpha, beta), max(alpha, beta)
            if ((hi < -half) or (lo > half)) or (hi == lo):
                continue
            first = max(int(math.ceil(((lo + half) / (2 * half)) * (_contour_points - 1))), 0)
            last = min(int(math.floor(((hi + half) / (2 * half)) * (_contour_points - 1))), _contour_points - 1)
            for k in range(first, last + 1):
                target = -half + (((2 * half) * float(k)) / (_contour_points - 1))
                s, c = math.sin(target), math.cos(target)
                den = ((b.x - a.x) * s) - ((b.y - a.y) * c)
                if den == 0:
                    continue
                u = ((a.y * c) - (a.x * s)) / den
                if (u < 0) or (u > 1):
                    continue
                r = ((a.x + (u * (b.x - a.x))) * c) + ((a.y + (u * (b.y - a.y))) * s)
                if not hit[k] or (r > reach[k]):
                    reach[k], hit[k] = r, True
    out = [None] * (_contour_points)
    for k in range(len(out)):
        angle = -half + (((2 * half) * float(k)) / (_contour_points - 1))
        r = p.DiskClearance + ((reach[k] + reach[(_contour_points - 1) - k]) / 2)
        out[k] = _Point(r * math.cos(angle), r * math.sin(angle))
    return out

def _split_at_inflections(points):
    runs = []
    start = 0
    sign = 0.0
    for i in range(1, len(points) - 1):
        a, b, c = points[i - 1], points[i], points[i + 1]
        turn = ((b.x - a.x) * (c.y - b.y)) - ((b.y - a.y) * (c.x - b.x))
        if turn == 0:
            continue
        if (sign != 0) and ((turn > 0) != (sign > 0)):
            runs = runs + [points[start:i + 1]]
            start = i
        sign = turn
    return runs + [points[start:]]

def _thinned(run, stride):
    out = []
    for i in range(0, len(run), stride):
        out = out + [run[i]]
    last = run[len(run) - 1]
    if out[len(out) - 1] != last:
        out = out + [last]
    return out

def _resolve(p):
    d = _Dimensions()
    n, m = float(p.PinCount), float(p.OutputPinCount)
    d.lobes = p.PinCount - 1
    d.pinCircleRadius = p.PinCircleDiameter / 2
    d.outputRadius = p.OutputPinCircleDiameter / 2
    if p.PinDiameter > 0:
        d.pinRadius = p.PinDiameter / 2
    else:
        d.pinRadius = (p.Eccentricity + (d.pinCircleRadius * math.sin(math.pi / n))) / 2
    d.effectiveRadius = d.pinRadius + p.DiskClearance
    d.rootRadius = (d.pinCircleRadius - d.effectiveRadius) - p.Eccentricity
    if p.OutputPinDiameter > 0:
        d.outputPinDiameter = p.OutputPinDiameter
    else:
        d.outputPinDiameter = (d.outputRadius * math.sin(math.pi / m)) - p.Eccentricity
    d.outputHoleDiameter = d.outputPinDiameter + (2 * p.Eccentricity)
    d.housingInner = 2 * ((d.pinCircleRadius - d.pinRadius) - p.HousingWall)
    d.housingOuter = 2 * (((d.pinCircleRadius - d.pinRadius) + (2 * p.Eccentricity)) + p.HousingWall)
    d.outputPlateDiameter = (p.OutputPinCircleDiameter + d.outputPinDiameter) + (2 * p.HousingWall)
    return d

def _min_inward_curvature_radius(r, e, n):
    nf = float(n)
    least = math.inf
    for i in range(_undercut_scan_points):
        t = ((2 * math.pi) * float(i)) / _undercut_scan_points
        sn, cn = math.sin(nf * t), math.cos(nf * t)
        st, ct = math.sin(t), math.cos(t)
        bx, by = (r * ct) - (e * cn), (-r * st) + (e * sn)
        xp, yp = (-r * st) + ((e * nf) * sn), (-r * ct) + ((e * nf) * cn)
        xpp, ypp = (-r * ct) + (((e * nf) * nf) * cn), (r * st) - (((e * nf) * nf) * sn)
        k = (xp * ypp) - (yp * xpp)
        if abs(k) < 1e-12:
            continue
        speed = math.hypot(xp, yp)
        rho = ((speed * speed) * speed) / k
        cx, cy = bx + (rho * (-yp / speed)), by + (rho * (xp / speed))
        if ((cx * cx) + (cy * cy)) < ((bx * bx) + (by * by)):
            least = min(least, abs(rho))
    return least

def _undercuts(p, e):
    q = p
    q.Eccentricity = e
    d = _resolve(q)
    return d.effectiveRadius >= _min_inward_curvature_radius(d.pinCircleRadius, e, p.PinCount)

def _undercut_bound(p):
    lo, hi = 1e-9, p.Eccentricity
    if _undercuts(p, lo):
        return 0
    for _ in range(40):
        mid = (lo + hi) / 2
        if _undercuts(p, mid):
            hi = mid
        else:
            lo = mid
    return lo

def problems(p):
    out = []
    def add(format, *args):
        nonlocal out
        out = out + [format % tuple(args)]
    if p.PinCount < 4:
        add("Pin Count must be at least 4 (currently %d).", p.PinCount)
    elif p.OutputPinCount < 3:
        add("Output Pin Count must be at least 3 (currently %d).", p.OutputPinCount)
    elif (p.DiscCount != 1) and (p.DiscCount != 2):
        add("Disc Count must be 1 or 2 (currently %d).", p.DiscCount)
    for f in [_Anonnamevaluezero("Pin Circle Diameter", p.PinCircleDiameter, False), _Anonnamevaluezero("Eccentricity", p.Eccentricity, False), _Anonnamevaluezero("Disc Thickness", p.DiscThickness, False), _Anonnamevaluezero("Center Bearing Diameter", p.CenterBearingDiameter, False), _Anonnamevaluezero("Output Pin Circle Diameter", p.OutputPinCircleDiameter, False), _Anonnamevaluezero("Housing Wall", p.HousingWall, False), _Anonnamevaluezero("Base Thickness", p.BaseThickness, False), _Anonnamevaluezero("Output Plate Thickness", p.OutputPlateThickness, False), _Anonnamevaluezero("Pin Diameter", p.PinDiameter, True), _Anonnamevaluezero("Disk Clearance", p.DiskClearance, True), _Anonnamevaluezero("Disc Gap", p.DiscGap, True), _Anonnamevaluezero("Input Shaft Diameter", p.InputShaftDiameter, True), _Anonnamevaluezero("Bearing Clearance", p.BearingClearance, True), _Anonnamevaluezero("Output Pin Diameter", p.OutputPinDiameter, True), _Anonnamevaluezero("Chamfer Size", p.ChamferSize, True)]:
        if math.isnan(f.value) or math.isinf(f.value):
            add("%s must be finite.", f.name)
        elif f.zero and (f.value < 0):
            add("%s must not be negative (currently %.2f mm).", f.name, f.value)
        elif not f.zero and (f.value <= 0):
            add("%s must be greater than 0 (currently %.2f mm).", f.name, f.value)
    if len(out) > 0:
        return out
    n, m = float(p.PinCount), float(p.OutputPinCount)
    d = _resolve(p)
    r, rop, e = d.pinCircleRadius, d.outputRadius, p.Eccentricity
    dhole, dpin = d.outputHoleDiameter, d.outputPinDiameter
    cbd, isd, clr = p.CenterBearingDiameter, p.InputShaftDiameter, p.BearingClearance
    if (p.DiscCount == 2) and (((p.PinCount % 2) != 0) or ((p.OutputPinCount % 2) != 0)):
        add("Two discs require an even Pin Count and an even Output Pin Count (currently N=%d, M=%d).", p.PinCount, p.OutputPinCount)
    if not ((e < d.pinRadius) and (d.pinRadius < (r * math.sin(math.pi / n)))):
        if p.PinDiameter == 0:
            add("Pin geometry out of range — increase Pin Circle Diameter above %.2f mm or reduce Eccentricity below %.2f mm.", (2 * e) / math.sin(math.pi / n), r * math.sin(math.pi / n))
        else:
            add("Pin Diameter must be between %.2f mm and %.2f mm (currently %.2f).", 2 * e, (2 * r) * math.sin(math.pi / n), 2 * d.pinRadius)
    if dpin <= 0:
        if p.OutputPinDiameter == 0:
            add("Output pins vanish (resolved diameter ≤ 0) — increase Output Pin Circle Diameter above %.2f mm, increase Output Pin Count, or reduce Eccentricity.", (2 * e) / math.sin(math.pi / m))
        else:
            add("Output Pin Diameter must be greater than 0.")
    if not (dhole < ((2 * rop) * math.sin(math.pi / m))):
        add("Output holes overlap — increase Output Pin Circle Diameter above %.2f mm, increase Output Pin Count, or reduce Output Pin Diameter / Eccentricity.", (dpin + (2 * e)) / math.sin(math.pi / m))
    if not (e < (r / n)):
        add("Eccentricity too large — reduce it below %.2f mm (or increase Pin Circle Diameter / reduce Pin Count).", r / n)
    if not (rop < d.rootRadius):
        add("Output Pin Circle too large — set Output Pin Circle Diameter below %.2f mm (currently %.2f).", 2 * d.rootRadius, 2 * rop)
    if _undercuts(p, e):
        bound = _undercut_bound(p)
        if bound > 0:
            add("Eccentricity too large — the rotor profile undercuts/self-intersects. Reduce Eccentricity below %.2f mm.", bound)
        else:
            add("Eccentricity too large — the rotor profile undercuts/self-intersects. Reduce Eccentricity.")
    if not (isd < cbd):
        add("Input Shaft Diameter must be less than Center Bearing Diameter (%.2f mm).", cbd)
    if not ((e + (isd / 2)) < (cbd / 2)):
        add("Input bore doesn't fit inside the cam — set Input Shaft Diameter below %.2f mm, or reduce Eccentricity / increase Center Bearing Diameter.", cbd - (2 * e))
    if not (((cbd + clr) / 2) < (rop - (dhole / 2))):
        add("Disk center bore overlaps the output holes — increase Output Pin Circle Diameter above %.2f mm, or reduce Center Bearing Diameter / Bearing Clearance / output pin size.", (cbd + clr) + dhole)
    return out

def _run_plane_at(r, height):
    if (height == 0) and (r.p.Placement is None):
        return r.world.xy()
    frame = _fx.r3_new_frame(r.frame.origin().add(r.frame.n().scale(height)), r.frame.u(), r.frame.v())
    return r.world.create_plane_from_frame(frame, name="Section Plane")

def _run_circle_at(r, s, x, y, diameter, expr):
    center = s.dimension_point(x, y)
    circle = s.create_circle(center, diameter / 2)
    dim = _fx.sketch_new_diameter(circle, diameter)
    s.add_constraint(dim)
    s.bind(dim, r.world.params(), expr)
    return circle

def _run_disc_geometry(r, index):
    cx = 0.0
    phi = 0.0
    if index == 0:
        return r.p.Eccentricity, 0
    return -r.p.Eccentricity, math.pi

def _run_disc_height(r, index):
    return float(index) * (r.p.DiscThickness + r.p.DiscGap)

def _run_build_disc(r, index):
    for limit in _lobe_turn_limits[:1]:
        body = None
        body = _run_build_disc_sampled(r, index, limit)
        if not False:
            return body
    return None

def _run_build_disc_sampled(r, index, turnLimit):
    p, d = r.p, r.d
    plane = _run_plane_at(r, _run_disc_height(r, index))
    s = r.world.create_sketch(plane, name="Disc Profile")
    cx, phi = _run_disc_geometry(r, index)
    segments = _lobe_segments(p, d, turnLimit)
    span = (2 * math.pi) / float(d.lobes)
    first = None
    shared = None
    for k in range(d.lobes):
        for i, segment in enumerate(segments):
            points = [None] * (len(segment))
            for j, t in enumerate(segment):
                if (j == 0) and (shared is not None):
                    points[j] = shared
                elif ((i == (len(segments) - 1)) and (j == (len(segment) - 1))) and (k == (d.lobes - 1)):
                    points[j] = first
                else:
                    q = _disc_point(p, d, t + (float(k) * span), cx, 0, phi)
                    points[j] = s.dimension_point(q.x, q.y)
            if first is None:
                first = points[0]
            shared = points[len(points) - 1]
            s.create_fit_spline(*points)
    _run_circle_at(r, s, cx, 0, p.CenterBearingDiameter + p.BearingClearance, "disc_bore_diameter")
    for j in range(p.OutputPinCount):
        angle = phi + (((2 * math.pi) * float(j)) / float(p.OutputPinCount))
        x = cx + (d.outputRadius * math.cos(angle))
        y = d.outputRadius * math.sin(angle)
        _run_circle_at(r, s, x, y, d.outputHoleDiameter, "output_hole_diameter")
    _solve_and_verify(s, "cycloidal: disc %d" % (index + 1,))
    profile = None
    for candidate in s.profiles():
        if candidate.Valid and (len(candidate.Holes) == (1 + p.OutputPinCount)):
            if profile is not None:
                raise RuntimeError("cycloidal: disc %d: more than one region has %d holes" % (index + 1, 1 + p.OutputPinCount,))
            profile = candidate
    if profile is None:
        raise RuntimeError("cycloidal: disc %d: no valid region with %d holes among %d regions" % (index + 1, 1 + p.OutputPinCount, len(s.profiles()),))
    thickness = r.doc.param("disc_thickness")
    body = _fx.decad_extrude(r.doc, s, profile, _fx.decad_distance(D=thickness, Dir=_fx.DECAD_ALONG), name="Disc Extrude", body="Disc")
    if not body.is_solid():
        raise RuntimeError("cycloidal: disc %d is not a solid" % (index + 1,))
    return body

def _run_build_housing(r):
    p, d = r.p, r.d
    stack = (float(p.DiscCount) * p.DiscThickness) + (float(p.DiscCount - 1) * p.DiscGap)
    bottom = -_plane_gap - p.BaseThickness
    outerPlane = _run_plane_at(r, bottom)
    os = r.world.create_sketch(outerPlane, name="Housing Outer Profile")
    _run_circle_at(r, os, 0, 0, d.housingOuter, "housing_outer_diameter")
    _solve_and_verify(os, "cycloidal: housing outer")
    outerProfile = _region_with_holes(os, 0, "cycloidal: housing outer")
    prism = _fx.decad_extrude(r.doc, os, outerProfile, _fx.decad_distance(D=_fx.units_millimeters(stack - bottom), Dir=_fx.DECAD_ALONG), name="Housing Outer Extrude", body="Housing")
    cavity = None
    for stride in _contour_strides[:1]:
        cavity = _run_build_cavity(r, stride)
        if not False:
            break
    walled = _fx.decad_cut(prism, cavity, name="Casing Cavity Cut")
    holePlane = _run_plane_at(r, bottom - 1)
    hs = r.world.create_sketch(holePlane, name="Housing Hole Profile")
    _run_circle_at(r, hs, 0, 0, d.housingInner, "housing_inner_diameter")
    _solve_and_verify(hs, "cycloidal: housing hole")
    holeProfile = _region_with_holes(hs, 0, "cycloidal: housing hole")
    hole = _fx.decad_extrude(r.doc, hs, holeProfile, _fx.decad_distance(D=_fx.units_millimeters(-bottom + 1), Dir=_fx.DECAD_ALONG), name="Housing Hole Extrude", body="Housing Hole Tool")
    housing = _fx.decad_cut(walled, hole, name="Housing Hole Cut")
    return housing

def _run_build_cavity(r, stride):
    p, d = r.p, r.d
    stack = (float(p.DiscCount) * p.DiscThickness) + (float(p.DiscCount - 1) * p.DiscGap)
    cavityPlane = _run_plane_at(r, -_plane_gap)
    cs = r.world.create_sketch(cavityPlane, name="Casing Profile")
    runs = _split_at_inflections(_housing_contour(p, d))
    pitch = (2 * math.pi) / float(p.PinCount)
    def rotate(q, k):
        s, c = math.sin(float(k) * pitch), math.cos(float(k) * pitch)
        return _Point((q.x * c) - (q.y * s), (q.x * s) + (q.y * c))
    first = None
    shared = None
    for k in range(p.PinCount):
        for i, run in enumerate(runs):
            run = _thinned(run, stride)
            points = [None] * (len(run))
            for j, q in enumerate(run):
                if (j == 0) and (shared is not None):
                    points[j] = shared
                elif ((i == (len(runs) - 1)) and (j == (len(run) - 1))) and (k == (p.PinCount - 1)):
                    points[j] = first
                else:
                    q = rotate(q, k)
                    points[j] = cs.dimension_point(q.x, q.y)
            if first is None:
                first = points[0]
            shared = points[len(points) - 1]
            cs.create_fit_spline(*points)
    _solve_and_verify(cs, "cycloidal: casing")
    cavityProfile = _region_with_holes(cs, 0, "cycloidal: casing")
    cavity = _fx.decad_extrude(r.doc, cs, cavityProfile, _fx.decad_distance(D=_fx.units_millimeters((stack + _plane_gap) + 1), Dir=_fx.DECAD_ALONG), name="Casing Cavity Extrude", body="Casing Cavity Tool")
    return cavity

def _run_build_cam(r):
    p = r.p
    sections = []
    for index in range(p.DiscCount):
        bottom, top = 0.0, p.DiscThickness + p.DiscGap
        if p.DiscCount == 1:
            top = p.DiscThickness
        if index == 1:
            bottom, top = p.DiscThickness, (2 * p.DiscThickness) + p.DiscGap
        if (p.DiscCount == 2) and (p.DiscGap == 0):
            if index == 0:
                top = top - (_cam_separation / 2)
            else:
                bottom = bottom + (_cam_separation / 2)
        plane = _run_plane_at(r, bottom)
        s = r.world.create_sketch(plane, name="Cam Section Profile")
        cx, _ = _run_disc_geometry(r, index)
        _run_circle_at(r, s, cx, 0, p.CenterBearingDiameter, "center_bearing_diameter")
        stage = "cycloidal: cam section %d" % (index + 1,)
        _solve_and_verify(s, stage)
        profile = _region_with_holes(s, 0, stage)
        section = _fx.decad_extrude(r.doc, s, profile, _fx.decad_distance(D=_fx.units_millimeters(top - bottom), Dir=_fx.DECAD_ALONG), name="Cam Section Extrude", body="Cam")
        sections = sections + [section]
    cam = sections[0]
    if len(sections) > 1:
        if p.DiscGap == 0:
            bridge = _run_build_cam_bridge(r)
            sections = sections + [bridge]
        cam = _fx.decad_union(sections[0], *sections[1:], name="Cam Join")
    if p.InputShaftDiameter == 0:
        return cam
    plane = _run_plane_at(r, -_plane_gap)
    s = r.world.create_sketch(plane, name="Input Bore Profile")
    _run_circle_at(r, s, 0, 0, p.InputShaftDiameter, "input_shaft_diameter")
    _solve_and_verify(s, "cycloidal: input bore")
    profile = _region_with_holes(s, 0, "cycloidal: input bore")
    height = ((float(p.DiscCount) * p.DiscThickness) + (float(p.DiscCount - 1) * p.DiscGap)) + (2 * _plane_gap)
    tool = _fx.decad_extrude(r.doc, s, profile, _fx.decad_distance(D=_fx.units_millimeters(height), Dir=_fx.DECAD_ALONG), name="Input Bore Extrude", body="Input Bore Tool")
    bored = _fx.decad_cut(cam, tool, name="Input Bore Cut")
    return bored

def _run_build_cam_bridge(r):
    p = r.p
    half = (_cam_separation / 2) + _cam_overlap
    plane = _run_plane_at(r, p.DiscThickness - half)
    s = r.world.create_sketch(plane, name="Cam Bridge Profile")
    inner = (p.CenterBearingDiameter / 2) - p.Eccentricity
    diameter = inner + (p.InputShaftDiameter / 2)
    circle = s.create_circle(s.origin(), diameter / 2)
    s.add_constraint(_fx.sketch_new_diameter(circle, diameter))
    _solve_and_verify(s, "cycloidal: cam bridge")
    profile = _region_with_holes(s, 0, "cycloidal: cam bridge")
    bridge = _fx.decad_extrude(r.doc, s, profile, _fx.decad_distance(D=_fx.units_millimeters(2 * half), Dir=_fx.DECAD_ALONG), name="Cam Bridge Extrude", body="Cam Bridge")
    return bridge

def _run_output_pin_center(r, j):
    angle = ((2 * math.pi) * float(j)) / float(r.p.OutputPinCount)
    return _Point(r.d.outputRadius * math.cos(angle), r.d.outputRadius * math.sin(angle))

def _run_build_output(r):
    p = r.p
    plateHeight = ((float(p.DiscCount) * p.DiscThickness) + (float(p.DiscCount - 1) * p.DiscGap)) + _plane_gap
    plane = _run_plane_at(r, plateHeight)
    ps = r.world.create_sketch(plane, name="Output Plate Profile")
    _run_circle_at(r, ps, 0, 0, r.d.outputPlateDiameter, "output_plate_diameter")
    for j in range(p.OutputPinCount):
        c = _run_output_pin_center(r, j)
        _run_circle_at(r, ps, c.x, c.y, r.d.outputPinDiameter, "resolved_output_pin_diameter")
    _solve_and_verify(ps, "cycloidal: output plate")
    plateProfile = _region_with_holes(ps, p.OutputPinCount, "cycloidal: output plate")
    thickness = r.doc.param("output_plate_thickness")
    plate = _fx.decad_extrude(r.doc, ps, plateProfile, _fx.decad_distance(D=thickness, Dir=_fx.DECAD_ALONG), name="Output Plate Extrude", body="Output Plate")
    pins = r.world.create_sketch(plane, name="Output Pin Profile")
    for j in range(p.OutputPinCount):
        c = _run_output_pin_center(r, j)
        _run_circle_at(r, pins, c.x, c.y, r.d.outputPinDiameter, "resolved_output_pin_diameter")
    _solve_and_verify(pins, "cycloidal: output pins")
    height = r.doc.param("output_plate_height")
    bodies = []
    for profile in pins.profiles():
        if not profile.Valid or (len(profile.Holes) != 0):
            raise RuntimeError("cycloidal: output pins: unexpected region")
        body = _fx.decad_extrude(r.doc, pins, profile, _fx.decad_two_sided(One=_fx.decad_distance_side(D=thickness), Two=_fx.decad_distance_side(D=height)), name="Output Pin Extrude", body="Output Pin")
        bodies = bodies + [body]
    if len(bodies) != p.OutputPinCount:
        raise RuntimeError("cycloidal: got %d output pins, want %d" % (len(bodies), p.OutputPinCount,))
    angles = {}
    for body in bodies:
        c = body.centroid()
        offset = c.Value.sub(r.frame.origin())
        angle = math.atan2(offset.dot(r.frame.v()), offset.dot(r.frame.u()))
        if angle < -1e-9:
            angle = angle + (2 * math.pi)
        angles[body] = angle
    bodies.sort(key=lambda _v: angles[_v])
    return plate, bodies

def _run_chamfered(r, body, what):
    return _run_chamfered_by(r, body, what, _fx.decad_edges(_fx.decad_outer_loop_of(_fx.decad_cap_start(body))).or_(_fx.decad_outer_loop_of(_fx.decad_cap_end(body))))

def _run_chamfered_by(r, body, what, sel):
    if r.p.ChamferSize == 0:
        return body
    size = r.doc.param("chamfer_size")
    out = _fx.decad_chamfer(body, sel, size, name="Chamfer " + what)
    return out

def _run_housing_outer_circles(r):
    longer = (math.pi * (r.d.housingOuter + r.d.housingInner)) / 2
    return _fx.decad_edges(_fx.decad_circular(), _fx.decad_longer_than(_fx.units_millimeters(longer))).exactly(2)

def build(doc, p):
    r = _begin(doc, p)
    drive = _Drive()
    for index in range(p.DiscCount):
        disc = _run_build_disc(r, index)
        drive.Discs = drive.Discs + [disc]
    drive.Cam = _run_build_cam(r)
    housing = _run_build_housing(r)
    drive.Housing = _run_chamfered_by(r, housing, "housing", _run_housing_outer_circles(r))
    plate, pins = _run_build_output(r)
    drive.OutputPlate = _run_chamfered(r, plate, "output plate")
    for i in range(len(pins)):
        pins[i] = _run_chamfered(r, pins[i], "output pin")
    drive.OutputPins = pins
    return drive

def disc_name(index):
    return "Cycloidal Disk %d" % (index + 1,)

def output_pin_name(index):
    return "Output Pin %d" % (index + 1,)

def drive_named(d):
    out = []
    for i, disc in enumerate(d.Discs):
        out = out + [_NamedBody(disc_name(i), disc)]
    out = out + [_NamedBody(_housing_name, d.Housing), _NamedBody(_cam_name, d.Cam), _NamedBody(_output_plate_name, d.OutputPlate)]
    for i, pin in enumerate(d.OutputPins):
        out = out + [_NamedBody(output_pin_name(i), pin)]
    return out


def _begin(doc, p):
    """The run the gallery's Build starts from: the design, the Params and the dimensions they resolve to."""
    return _Run(doc=doc, world=doc, p=p, d=_resolve(p), frame=_placement(p))


def _params_of_inputs(inputs: adsk.core.CommandInputs):
    return _Params(
        PinCount=int(round(inputs.itemById(INPUT_ID_PIN_COUNT).value)),
        PinCircleDiameter=to_mm(inputs.itemById(INPUT_ID_PIN_CIRCLE_DIAMETER).value),
        PinDiameter=to_mm(inputs.itemById(INPUT_ID_PIN_DIAMETER).value),
        Eccentricity=to_mm(inputs.itemById(INPUT_ID_ECCENTRICITY).value),
        DiskClearance=to_mm(inputs.itemById(INPUT_ID_DISK_CLEARANCE).value),
        DiscCount=int(inputs.itemById(INPUT_ID_DISC_COUNT).selectedItem.name),
        DiscThickness=to_mm(inputs.itemById(INPUT_ID_DISC_THICKNESS).value),
        DiscGap=to_mm(inputs.itemById(INPUT_ID_DISC_GAP).value),
        CenterBearingDiameter=to_mm(inputs.itemById(INPUT_ID_CENTER_BEARING_DIAMETER).value),
        InputShaftDiameter=to_mm(inputs.itemById(INPUT_ID_INPUT_SHAFT_DIAMETER).value),
        BearingClearance=to_mm(inputs.itemById(INPUT_ID_BEARING_CLEARANCE).value),
        OutputPinCircleDiameter=to_mm(inputs.itemById(INPUT_ID_OUTPUT_PIN_CIRCLE_DIAMETER).value),
        OutputPinCount=int(round(inputs.itemById(INPUT_ID_OUTPUT_PIN_COUNT).value)),
        OutputPinDiameter=to_mm(inputs.itemById(INPUT_ID_OUTPUT_PIN_DIAMETER).value),
        HousingWall=to_mm(inputs.itemById(INPUT_ID_WALL).value),
        BaseThickness=to_mm(inputs.itemById(INPUT_ID_BASE_THICKNESS).value),
        OutputPlateThickness=to_mm(inputs.itemById(INPUT_ID_OUTPUT_PLATE_THICKNESS).value),
        ChamferSize=to_mm(inputs.itemById(INPUT_ID_CHAMFER_SIZE).value),
        Placement=None,
    )


# -----------------------------------------------------------------------------------------
# The orchestrator: the Fusion wiring around the translated build.
# -----------------------------------------------------------------------------------------
class CycloidalDriveGenerator(Generator):
    DEFAULT_STATUS_INPUT_ID = INPUT_ID_PIN_CIRCLE_DIAMETER + '__status'

    # The groups the drive's bodies are moved into, as sub-components. Fusion-only organisation.
    COMPONENT_GROUPS = (
        ('Rotor Discs', lambda name: name.startswith('Cycloidal Disk')),
        ('Housing', lambda name: name == 'Housing'),
        ('Eccentric Cam', lambda name: name == 'Eccentric Cam'),
        ('Output', lambda name: name == 'Output Plate' or name.startswith('Output Pin')),
    )

    def prefixBase(self) -> str:
        return 'CycloidalDrive'

    def generateName(self) -> str:
        N = int(round(self.getParameter(PARAM_PIN_COUNT).value))
        L = N - 1
        return 'Cycloidal Drive (N={}):{}'.format(N, L)

    @staticmethod
    def validate_inputs(inputs: adsk.core.CommandInputs) -> list:
        return problems(_params_of_inputs(inputs))

    def _galleryParams(self):
        value = lambda constant: self.getParameter(constant).value
        return _Params(
            PinCount=int(round(value(PARAM_PIN_COUNT))),
            PinCircleDiameter=to_mm(value(PARAM_PIN_CIRCLE_DIAMETER)),
            PinDiameter=to_mm(value(PARAM_PIN_DIAMETER)),
            Eccentricity=to_mm(value(PARAM_ECCENTRICITY)),
            DiskClearance=to_mm(value(PARAM_DISK_CLEARANCE)),
            DiscCount=int(round(value(PARAM_DISC_COUNT))),
            DiscThickness=to_mm(value(PARAM_DISC_THICKNESS)),
            DiscGap=to_mm(value(PARAM_DISC_GAP)),
            CenterBearingDiameter=to_mm(value(PARAM_CENTER_BEARING_DIAMETER)),
            InputShaftDiameter=to_mm(value(PARAM_INPUT_SHAFT_DIAMETER)),
            BearingClearance=to_mm(value(PARAM_BEARING_CLEARANCE)),
            OutputPinCircleDiameter=to_mm(value(PARAM_OUTPUT_PIN_CIRCLE_DIAMETER)),
            OutputPinCount=int(round(value(PARAM_OUTPUT_PIN_COUNT))),
            OutputPinDiameter=to_mm(value(PARAM_OUTPUT_PIN_DIAMETER)),
            HousingWall=to_mm(value(PARAM_WALL)),
            BaseThickness=to_mm(value(PARAM_BASE_THICKNESS)),
            OutputPlateThickness=to_mm(value(PARAM_OUTPUT_PLATE_THICKNESS)),
            ChamferSize=to_mm(value(PARAM_CHAMFER_SIZE)),
            Placement=None,
        )

    def processInputs(self, inputs: adsk.core.CommandInputs):
        self.plane = adsk.fusion.ConstructionPlane.cast(None)
        self.anchorPoint = adsk.fusion.SketchPoint.cast(None)
        self._runtime = None

        # Selections first ([PB-SELECTION-STASH]).
        parentEntities = get_selection(inputs, INPUT_ID_PARENT)
        if parentEntities:
            parentEntity = parentEntities[0]
            if parentEntity.objectType == adsk.fusion.Occurrence.classType():
                self.parentComponent = parentEntity.component
            else:
                self.parentComponent = parentEntity
        else:
            self.parentComponent = get_design().rootComponent
        self.plane = get_selection(inputs, INPUT_ID_PLANE)[0]
        self.anchorPoint = get_selection(inputs, INPUT_ID_ANCHOR_POINT)[0]

        # The dialog's values, registered as user parameters ([PB-GET-VALUE-CONTRACT]).
        self.addParameter(
            PARAM_PIN_COUNT, get_value(inputs, INPUT_ID_PIN_COUNT, ''), '', 'Pin Count')
        self.addParameter(
            PARAM_PIN_CIRCLE_DIAMETER, get_value(inputs, INPUT_ID_PIN_CIRCLE_DIAMETER, 'mm'), 'mm', 'Pin Circle Diameter')
        self.addParameter(
            PARAM_PIN_DIAMETER, get_value(inputs, INPUT_ID_PIN_DIAMETER, 'mm'), 'mm', 'Pin Diameter')
        self.addParameter(
            PARAM_ECCENTRICITY, get_value(inputs, INPUT_ID_ECCENTRICITY, 'mm'), 'mm', 'Eccentricity')
        self.addParameter(
            PARAM_DISK_CLEARANCE, get_value(inputs, INPUT_ID_DISK_CLEARANCE, 'mm'), 'mm', 'Disk Clearance')
        self.addParameter(
            PARAM_DISC_COUNT,
            adsk.core.ValueInput.createByReal(int(inputs.itemById(INPUT_ID_DISC_COUNT).selectedItem.name)), '', 'Disc Count')
        self.addParameter(
            PARAM_DISC_THICKNESS, get_value(inputs, INPUT_ID_DISC_THICKNESS, 'mm'), 'mm', 'Disc Thickness')
        self.addParameter(
            PARAM_DISC_GAP, get_value(inputs, INPUT_ID_DISC_GAP, 'mm'), 'mm', 'Disc Gap')
        self.addParameter(
            PARAM_CENTER_BEARING_DIAMETER, get_value(inputs, INPUT_ID_CENTER_BEARING_DIAMETER, 'mm'), 'mm', 'Center Bearing Diameter')
        self.addParameter(
            PARAM_INPUT_SHAFT_DIAMETER, get_value(inputs, INPUT_ID_INPUT_SHAFT_DIAMETER, 'mm'), 'mm', 'Input Shaft Diameter')
        self.addParameter(
            PARAM_BEARING_CLEARANCE, get_value(inputs, INPUT_ID_BEARING_CLEARANCE, 'mm'), 'mm', 'Bearing Clearance')
        self.addParameter(
            PARAM_OUTPUT_PIN_CIRCLE_DIAMETER, get_value(inputs, INPUT_ID_OUTPUT_PIN_CIRCLE_DIAMETER, 'mm'), 'mm', 'Output Pin Circle Diameter')
        self.addParameter(
            PARAM_OUTPUT_PIN_COUNT, get_value(inputs, INPUT_ID_OUTPUT_PIN_COUNT, ''), '', 'Output Pin Count')
        self.addParameter(
            PARAM_OUTPUT_PIN_DIAMETER, get_value(inputs, INPUT_ID_OUTPUT_PIN_DIAMETER, 'mm'), 'mm', 'Output Pin Diameter')
        self.addParameter(
            PARAM_WALL, get_value(inputs, INPUT_ID_WALL, 'mm'), 'mm', 'Housing Wall')
        self.addParameter(
            PARAM_BASE_THICKNESS, get_value(inputs, INPUT_ID_BASE_THICKNESS, 'mm'), 'mm', 'Base Thickness')
        self.addParameter(
            PARAM_OUTPUT_PLATE_THICKNESS, get_value(inputs, INPUT_ID_OUTPUT_PLATE_THICKNESS, 'mm'), 'mm', 'Output Plate Thickness')
        self.addParameter(
            PARAM_CHAMFER_SIZE, get_value(inputs, INPUT_ID_CHAMFER_SIZE, 'mm'), 'mm', 'Chamfer Size')

        # The gallery's validity checks, then the dimensions the rest of the table needs.
        params = self._galleryParams()
        found = problems(params)
        if found:
            raise Exception('\n'.join(found))
        dims = _resolve(params)
        expression = '{} - 1'.format(
            self.parameterName(PARAM_PIN_COUNT))
        self.addParameter(
            PARAM_LOBES, adsk.core.ValueInput.createByString(expression),
            '', 'Lobes')
        expression = '{} / 2'.format(
            self.parameterName(PARAM_PIN_CIRCLE_DIAMETER))
        self.addParameter(
            PARAM_PIN_CIRCLE_RADIUS, adsk.core.ValueInput.createByString(expression),
            'mm', 'Pin Circle Radius')
        expression = '{} / 2'.format(
            self.parameterName(PARAM_OUTPUT_PIN_CIRCLE_DIAMETER))
        self.addParameter(
            PARAM_OUTPUT_PIN_CIRCLE_RADIUS, adsk.core.ValueInput.createByString(expression),
            'mm', 'Output Pin Circle Radius')
        self.addParameter(
            PARAM_PIN_RADIUS, adsk.core.ValueInput.createByReal(to_cm(dims.pinRadius)),
            'mm', 'Pin Radius (numeric snapshot)')
        self.addParameter(
            PARAM_OUTPUT_HOLE_DIAMETER, adsk.core.ValueInput.createByReal(to_cm(dims.outputHoleDiameter)),
            'mm', 'Output Hole Diameter (numeric snapshot)')
        expression = '2 * ({} - {} - {} - {})'.format(
            self.parameterName(PARAM_PIN_CIRCLE_RADIUS),
            self.parameterName(PARAM_PIN_RADIUS),
            self.parameterName(PARAM_DISK_CLEARANCE),
            self.parameterName(PARAM_ECCENTRICITY))
        self.addParameter(
            PARAM_ROOT_CIRCLE_DIAMETER, adsk.core.ValueInput.createByString(expression),
            'mm', 'Root Circle Diameter')
        expression = '2 * ({} - {} - {})'.format(
            self.parameterName(PARAM_PIN_CIRCLE_RADIUS),
            self.parameterName(PARAM_PIN_RADIUS),
            self.parameterName(PARAM_WALL))
        self.addParameter(
            PARAM_HOUSING_INNER_DIAMETER, adsk.core.ValueInput.createByString(expression),
            'mm', 'Housing Inner Diameter')
        expression = '2 * ({} - {} + 2 * {} + {})'.format(
            self.parameterName(PARAM_PIN_CIRCLE_RADIUS),
            self.parameterName(PARAM_PIN_RADIUS),
            self.parameterName(PARAM_ECCENTRICITY),
            self.parameterName(PARAM_WALL))
        self.addParameter(
            PARAM_HOUSING_OUTER_DIAMETER, adsk.core.ValueInput.createByString(expression),
            'mm', 'Housing Outer Diameter')
        expression = '{} + {}'.format(
            self.parameterName(PARAM_CENTER_BEARING_DIAMETER),
            self.parameterName(PARAM_BEARING_CLEARANCE))
        self.addParameter(
            PARAM_DISC_BORE_DIAMETER, adsk.core.ValueInput.createByString(expression),
            'mm', 'Disc Bore Diameter')
        expression = '{} - 2 * {}'.format(
            self.parameterName(PARAM_OUTPUT_HOLE_DIAMETER),
            self.parameterName(PARAM_ECCENTRICITY))
        self.addParameter(
            PARAM_RESOLVED_OUTPUT_PIN_DIAMETER, adsk.core.ValueInput.createByString(expression),
            'mm', 'Resolved Output Pin Diameter')
        expression = '{} + {} + 2 * {}'.format(
            self.parameterName(PARAM_OUTPUT_PIN_CIRCLE_DIAMETER),
            self.parameterName(PARAM_RESOLVED_OUTPUT_PIN_DIAMETER),
            self.parameterName(PARAM_WALL))
        self.addParameter(
            PARAM_OUTPUT_PLATE_DIAMETER, adsk.core.ValueInput.createByString(expression),
            'mm', 'Output Plate Diameter')
        self.addParameter(
            PARAM_PLANE_GAP, adsk.core.ValueInput.createByReal(to_cm(1)),
            'mm', 'Plane Gap')
        expression = '{} + {}'.format(
            self.parameterName(PARAM_DISC_THICKNESS),
            self.parameterName(PARAM_DISC_GAP))
        self.addParameter(
            PARAM_DISC_PITCH, adsk.core.ValueInput.createByString(expression),
            'mm', 'Disc Pitch')
        expression = '{} * {} + {} * ({} - 1)'.format(
            self.parameterName(PARAM_DISC_THICKNESS),
            self.parameterName(PARAM_DISC_COUNT),
            self.parameterName(PARAM_DISC_GAP),
            self.parameterName(PARAM_DISC_COUNT))
        self.addParameter(
            PARAM_STACK_HEIGHT, adsk.core.ValueInput.createByString(expression),
            'mm', 'Stack Height')
        expression = '{} + {}'.format(
            self.parameterName(PARAM_STACK_HEIGHT),
            self.parameterName(PARAM_PLANE_GAP))
        self.addParameter(
            PARAM_OUTPUT_PLATE_HEIGHT, adsk.core.ValueInput.createByString(expression),
            'mm', 'Output Plate Height')
        expression = '{} + {}'.format(
            self.parameterName(PARAM_OUTPUT_PLATE_HEIGHT),
            self.parameterName(PARAM_OUTPUT_PLATE_THICKNESS))
        self.addParameter(
            PARAM_OUTPUT_PIN_LENGTH, adsk.core.ValueInput.createByString(expression),
            'mm', 'Output Pin Length')

    def galleryParameter(self, name):
        """The Fusion name and user parameter of a gallery parameter table entry."""
        constant = _GALLERY_PARAMETERS[name]
        return self.parameterName(constant), self.getParameter(constant)

    def generate(self, inputs: adsk.core.CommandInputs):
        self.processInputs(inputs)

        component = self.getComponent()
        component.name = self.generateName()

        # Normalise the Target Plane to a ConstructionPlane.
        if self.plane.objectType != adsk.fusion.ConstructionPlane.classType():
            planeInput = component.constructionPlanes.createInput()
            planeInput.setByOffset(self.plane, adsk.core.ValueInput.createByReal(0))
            self.plane = component.constructionPlanes.add(planeInput)
            self.plane.name = 'Drive Base Plane'

        toolsSketch = self._anchor(component)
        runtime = _fx.Runtime(component, self.plane, self._projectedAnchor, self.galleryParameter, False, MILLIMETRE)
        runtime.activate()
        self._runtime = runtime
        runtime.build_frame(toolsSketch)
        drive = build(runtime, self._galleryParams())
        for named in drive_named(drive):
            named.Body.body.name = named.Name
        self._buildSubComponents(component)
        runtime.hide_helpers()
        toolsSketch.isVisible = False
        solids.hide_construction_geometry(component)

    def _anchor(self, component):
        """A sketch on the plane that holds the Anchor Point, fully constrained, for every translated sketch to
        project. [CYCLOIDAL-F-ANCHOR-CHAIN]"""
        sketch: adsk.fusion.Sketch = component.sketches.add(self.plane)
        sketch.name = 'Tools'
        self._projectedAnchor = adsk.fusion.SketchPoint.cast(sketch.project(self.anchorPoint).item(0))
        if self._projectedAnchor is None:
            raise RuntimeError('Tools: anchor projection produced no SketchPoint')
        if not sketch.isFullyConstrained:
            raise RuntimeError(f'{sketch.name}: sketch is not fully constrained')
        return sketch

    def _buildSubComponents(self, component: adsk.fusion.Component):
        """Move the drive's bodies into one sub-component per group, last, because moveToComponent invalidates the
        moved body's reference."""
        groups = {name: [] for name, _ in self.COMPONENT_GROUPS}
        for i in range(component.bRepBodies.count):
            body = component.bRepBodies.item(i)
            for name, belongs in self.COMPONENT_GROUPS:
                if belongs(body.name):
                    groups[name].append(body)
                    break
        for name, _ in self.COMPONENT_GROUPS:
            bodies = groups[name]
            if not bodies:
                continue
            occurrence = component.occurrences.addNewComponent(adsk.core.Matrix3D.create())
            occurrence.component.name = name
            for body in bodies:
                body.moveToComponent(occurrence)
